<?php $editando = !empty($produtoEditando); function esc($value) { return htmlspecialchars((string)($value ?? ''), ENT_QUOTES, 'UTF-8'); } ?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Produtos | Mercado+</title><link rel="stylesheet" href="style.css"></head><body><div class="shell"><aside class="sidebar"><div class="brand">mercado<span>+</span></div><div class="nav-label">Operação</div><nav class="nav"><a href="index.php">⌂ &nbsp; Visão geral</a><a class="active" href="index.php?controller=produto">▦ &nbsp; Produtos</a><a href="index.php?controller=estoque">↕ &nbsp; Estoque</a><a href="index.php?controller=pdv">▣ &nbsp; Caixa / PDV</a><a href="index.php?controller=vendas&action=listar">◷ &nbsp; Vendas</a></nav></aside><main class="main"><header class="topline"><div><p class="eyebrow">Cadastro</p><h1>Produtos</h1><p class="muted">Mantenha o catálogo e os preços do supermercado.</p></div><a class="button" href="index.php?controller=produto&action=novo">+ Novo produto</a></header><section class="panel"><div class="panel-head"><h2><?= $editando ? 'Editar produto' : 'Cadastrar produto' ?></h2><?php if ($editando): ?><a class="button light" href="index.php?controller=produto">Cancelar</a><?php endif; ?></div><form method="post" action="index.php?controller=produto&action=<?= $editando ? 'atualizar&id=' . (int)$produtoEditando['id'] : 'cadastrar' ?>"><div class="form-grid"><div class="field"><label for="codigo">Código de barras</label><input id="codigo" name="codigo" required value="<?= esc($produtoEditando['codigo'] ?? '') ?>"></div><div class="field"><label for="descricao">Descrição</label><input id="descricao" name="descricao" required value="<?= esc($produtoEditando['descricao'] ?? '') ?>"></div><div class="field"><label for="custo">Custo (R$)</label><input id="custo" name="custo" type="number" step="0.01" min="0" required value="<?= esc($produtoEditando['custo'] ?? '0') ?>"></div><div class="field"><label for="preco_venda">Preço de venda (R$)</label><input id="preco_venda" name="preco_venda" type="number" step="0.01" min="0" required value="<?= esc($produtoEditando['preco_venda'] ?? '0') ?>"></div><div class="field"><label for="estoque">Estoque atual</label><input id="estoque" name="estoque" type="number" min="0" required value="<?= esc($produtoEditando['estoque'] ?? '0') ?>"></div><div class="field"><label for="ativo">Status</label><select id="ativo" name="ativo"><option value="1" <?= (($produtoEditando['ativo'] ?? 1) == 1) ? 'selected' : '' ?>>Ativo</option><option value="0" <?= (($produtoEditando['ativo'] ?? 1) == 0) ? 'selected' : '' ?>>Inativo</option></select></div></div><div class="form-actions"><button class="button" type="submit"><?= $editando ? 'Salvar alterações' : 'Cadastrar produto' ?></button></div></form></section><section class="panel"><div class="panel-head"><h2>Catálogo</h2><span class="muted"><?= count($produtos) ?> itens cadastrados</span></div><div class="table-wrap"><table><thead><tr><th>Código</th><th>Descrição</th><th>Preço</th><th>Estoque</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($produtos as $produto): ?><tr><td><?= esc($produto['codigo']) ?></td><td><strong><?= esc($produto['descricao']) ?></strong></td><td>R$ <?= number_format((float)$produto['preco_venda'], 2, ',', '.') ?></td><td><?= (int)$produto['estoque'] ?></td><td><span class="badge <?= !$produto['ativo'] ? 'out' : '' ?>"><?= $produto['ativo'] ? 'Ativo' : 'Inativo' ?></span></td><td><a class="button light" href="index.php?controller=produto&action=editar&id=<?= (int)$produto['id'] ?>">Editar</a> <a class="button danger" href="index.php?controller=produto&action=excluir&id=<?= (int)$produto['id'] ?>" onclick="return confirm('Excluir este produto?')">Excluir</a></td></tr><?php endforeach; ?></tbody></table><?php if (!$produtos): ?><div class="empty">Nenhum produto cadastrado ainda.</div><?php endif; ?></div></section></main></div></body></html>
